Naum 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Sobre qual cidade é a sentença registrada na visão de Naum?","o":["Nínive","Babilônia","Samaria","Damasco"],"c":0,"v":1,"e":"O capítulo começa com \"Sentença sobre Nínive\", no versículo 1."},
 {"t":"multipla","p":"Segundo o capítulo, as nuvens são o quê?","o":["O manto do Senhor","O pó de seus pés","O carro do Senhor","A sua morada"],"c":1,"v":3,"e":"O versículo 3 diz que \"as nuvens são o pó de seus pés\"."},
 {"t":"multipla","p":"As pastagens de quais lugares murcham diante do Senhor?","o":["Gileade e Hermom","Sarom e Moabe","Basã e Carmelo","Edom e Seir"],"c":2,"v":4,"e":"O versículo 4 diz que \"as pastagens de Basã e do Carmelo murcham\"."},
 {"t":"multipla","p":"O Senhor é bom e é fortaleza em que dia?","o":["No dia da festa","No dia da colheita","No dia do sábado","No dia da angústia"],"c":3,"v":7,"e":"O versículo 7 diz que o Senhor \"é fortaleza no dia da angústia\"."},
 {"t":"multipla","p":"Com o que o Senhor acabará de uma vez com o lugar da cidade?","o":["Com uma inundação transbordante","Com fogo do céu","Com um grande terremoto","Com a espada de um rei estrangeiro"],"c":0,"v":8,"e":"O versículo 8 diz: \"Com uma inundação transbordante, Ele acabará de uma vez com o lugar desta cidade\"."},
 {"t":"cv","p":"Os inimigos, ainda que se entrelacem como espinhos, serão consumidos como palha seca.","c":true,"v":10,"e":"O versículo 10 diz que \"serão inteiramente consumidos como palha seca\"."},
 {"t":"cv","p":"O capítulo diz que da cidade surgiu um conselheiro fiel, que buscou o bem diante do Senhor.","c":false,"v":11,"e":"O versículo 11 diz que surgiu alguém que \"tramou o mal contra o Senhor, um conselheiro vil\"."},
 {"t":"cv","p":"Judá é chamado a celebrar suas festas e cumprir seus votos, porque o ímpio não passará mais por ele.","c":true,"v":15,"e":"O versículo 15 diz: \"Celebre suas festas, ó Judá, cumpra seus votos, pois o homem ímpio não passará mais por você\"."}
]}

Naum 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como o capítulo descreve a cidade logo no início?","o":["Cheia de mentiras e de roubo","Cheia de ídolos e de altares","Cheia de riquezas e de festas","Cheia de soldados e de muralhas"],"c":0,"v":1,"e":"O versículo 1 chama a cidade de sanguinária, cheia de mentiras e de roubo."},
 {"t":"multipla","p":"Que cidade os que a virem dirão que está destruída?","o":["Samaria","Nínive","Babilônia","No-Amon"],"c":1,"v":7,"e":"No versículo 7, os que a veem fogem e dizem: Nínive está destruída!"},
 {"t":"multipla","p":"Quem estava à disposição para socorrer No-Amon?","o":["Assíria e Babilônia","Edom e Moabe","Put e Líbia","Judá e Israel"],"c":2,"v":9,"e":"O versículo 9 diz que Put e Líbia estavam à disposição para socorrê-la."},
 {"t":"multipla","p":"A que são comparadas as fortalezas da cidade?","o":["Torres de areia","Casas de palha","Cisternas rachadas","Figueiras com figos precoces"],"c":3,"v":12,"e":"O versículo 12 compara as fortalezas a figueiras com figos precoces, que caem na boca de quem as come quando sacudidas."},
 {"t":"multipla","p":"O que fazem os gafanhotos acampados nas cercas quando o sol surge?","o":["Voam embora, e não se sabe mais onde estavam","Morrem com o calor","Devoram toda a plantação","Ficam parados nas cercas"],"c":0,"v":17,"e":"O versículo 17 diz que, quando o sol surge, eles voam embora e não se conhece mais o lugar onde estavam."},
 {"t":"cv","p":"No-Amon escapou do exílio porque estava cercada por águas.","c":false,"v":10,"e":"O versículo 10 diz que, apesar de tudo, No-Amon foi levada ao exílio."},
 {"t":"cv","p":"Os pastores do rei da Assíria estão vigilantes e reúnem o povo.","c":false,"v":18,"e":"O versículo 18 diz que os pastores dormem e o povo se dispersa pelos montes sem ninguém que o reúna."},
 {"t":"cv","p":"Todos os que ouvirem a fama do rei da Assíria baterão palmas sobre ele.","c":true,"v":19,"e":"O versículo 19 diz que todos os que ouvirem a sua fama baterão palmas sobre ele."}
]}

Naum 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Contra qual cidade o destruidor avança?","o":["Jerusalém","Babilônia","Nínive","Samaria"],"c":2,"v":1,"e":"O versículo 1 diz: \"O destruidor avança contra você, ó Nínive!\""},
 {"t":"multipla","p":"O que o Senhor restaurará?","o":["A glória de Jacó","Os muros de Nínive","O trono de Davi","O templo de Jerusalém"],"c":0,"v":2,"e":"O versículo 2 diz que o Senhor restaurará a glória de Jacó, assim como a glória de Israel."},
 {"t":"multipla","p":"Como estarão os escudos dos valentes?","o":["Dourados","Vermelhos","Quebrados","Escondidos"],"c":1,"v":3,"e":"O versículo 3 diz que os escudos dos valentes estarão vermelhos."},
 {"t":"multipla","p":"O que acontece quando as comportas do rio se abrem?","o":["A cidade fica cercada","O povo foge para o deserto","Os carros são arrastados","O palácio é arrasado"],"c":3,"v":6,"e":"O versículo 6 diz que as comportas do rio se abrirão e o palácio será arrasado."},
 {"t":"multipla","p":"Desde que existe, Nínive tem sido como o quê?","o":["Uma torre forte","Um jardim fértil","Um tanque de águas","Uma rocha firme"],"c":2,"v":8,"e":"O versículo 8 diz que Nínive, desde que existe, tem sido como um tanque de águas."},
 {"t":"cv","p":"O texto diz que os tesouros de Nínive eram poucos.","c":false,"v":9,"e":"O versículo 9 diz o contrário: os tesouros não se acabam e há profusão de objetos desejáveis."},
 {"t":"cv","p":"O leão trazia o bastante para seus filhotes e estrangulava a presa para suas leoas.","c":true,"v":12,"e":"O versículo 12 diz exatamente isso sobre o leão."},
 {"t":"cv","p":"O Senhor dos Exércitos diz que a voz dos embaixadores de Nínive continuará sendo ouvida.","c":false,"v":13,"e":"No versículo 13 o Senhor diz que já não se ouvirá mais a voz dos embaixadores."}
]}
